window.__D("text/torat-chaim/c039",{"p":[[2300550368,"ע\"כ נא' בו לו דומיה תהלה<sup data-n=\"9767\">281</sup> כו' ו[כן] נק' נורא תהלות<sup data-n=\"9768\">282</sup> כו' לפי שהוא אדון הנפלאות<sup data-n=\"9769\">283</sup> בבחי' סדכ\"ס דלא ידיע לי' בר איהו כו', [ל]פי שאוא\"ס אין לו שיעור למעלה בעילוי אחר עילוי כו' וגם למטה מטה כו' ע\"כ גם אין לו הפסק בתשבחות כלל כי כל מה שאתה משבח יותר עדיין לא הגעת [גם] לחצי השבח לפי שאין לו הפסק ושיעור עד שדומיה תהלה. וזהו הטעם שנשמות הגבוהות כמשה ואהרן והאבות שנקראים קדושים<sup data-n=\"9770\">284</sup> גם עכשיו הן עולים תמיד בעילוי אחר עילוי בשבח דרוממות דא\"ס בלי הפסק כלל וכמ\"ש ילכו מחיל אל חיל<sup data-n=\"9771\">285</sup> כו' (עד שגם בעוה\"ב שנק' מנוחה לחיי העולמים<sup data-n=\"9772\">286</sup> אין לת\"ח מנוחה<sup data-n=\"9773\">287</sup> בעליות רבות מטעם הנ\"ל). וזהו משובח ומפואר בלשון חסידיו ועבדיו חסידי[ו] הן הנשמות ועבדי[ו] הן המלאכים<sup data-n=\"9774\">288</sup> שמצמצם א\"ע <span data-k=\"pg\">1312</span> ּ להיות מהולל בהם כפי מדריגתם לבד כו' עד שמשובח ומפואר [ל]מעלה עד אין קץ ושיעור<sup data-n=\"9775\">289</sup> בנשמות דוקא והוא עדי עד בבחי' נצחי[ו]' דא\"ס שהוא שמו הגדול בבחי' מל' דא\"ס (והוא לפי שהנשמות נק' מהלכים<sup data-n=\"9776\">290</sup> שיכולה לילך בעילוי אחר עילוי בבחי' נצחיות דא\"ס ממש, וז\"ש ירוממוך סלה בלי הפסק, משא\"כ המלאכים לפי ששרשם מקו המדה<sup data-n=\"9777\">291</sup> שבאורות וכלים דאבי\"ע היינו ע\"י האותיות שבבחי' מל' שלזה נק' עומדים בלי תוספת ומגרעת, אבל הנשמות שרשם בעצמות אור א\"ס שלפני הצמצום דקו וחוט כו' כידוע וכמ\"ש במ\"א וד\"ל (וזהו אינו בא רק ע\"י בחי' כת\"ר שנעשה מבחי' אור חוזר דבע\"ת בסור מרע בלאו שקודם להן כו', עי\"ז דוקא שעולים למעלה מעלה שהוא בחי' ההעלם דכת\"ר עצמו שנק' שם סתימא דכל סתימין דלית מח' תפיסא בי' כלל, שם דוקא הוא נצחיות דעדי עד שהוא בעלי' דרוממות והעלם העצמות דא\"ס שעולה באין שיעור למעלה שלא יוכל לבוא [ו]לשכון בשום כלי רק [ב]בחי' העדר וביטול דאין ומ\"ה דחכ' כו') וד\"ל.\n<b>והנה</b><sup data-n=\"9778\">292</sup> יש עוד פי' רביעי<sup data-n=\"9779\">293</sup> בעדי היפך מפי' הנצחיות הנ\"ל, והוא מלשון הפסק<sup data-n=\"9780\">294</sup> ושעור דוקא כמו עד כאן תחום שבת<sup data-n=\"9781\">295</sup> וכה\"ג שזהו ענין הגבול והשעור דוקא עד כאן ותו לא, וכמו עד ולא עד בכלל<sup data-n=\"9782\">296</sup> (וכן עד יעבור<sup data-n=\"9783\">297</sup> עד יקום גוי<sup data-n=\"9784\">298</sup> עד כי יבא שילה<sup data-n=\"9785\">299</sup> כו' שר\"ל עד אותו הזמן כי עד זה הוא זמן המופסק וכן עד מקום פלוני, ויש בו ג\"כ היפוכו שהוא ענין נצחי כמו מעולם ועד עולם<sup data-n=\"9786\">300</sup> וכן ימלוך לעולם ועד<sup data-n=\"9787\">301</sup> ונצח סלה ועד אין לו הפסק כו'<sup data-n=\"9788\">302</sup> ). אך עכ\"ז יש לפרש בפי' זה דעד ענין הפסק",[["9767","281","<b>לו דומיה תהלה</b>: תהלים סה, ב [ושם: לך — ראה גם לקמן הערה 303. לעיל פ' וארא סא, ב. בשלח קסז, ג]."],["9768","282","<b>נורא תהלות</b>: בשלח טו, יא."],["9769","283","<b>נורא תהלות. . אדון הנפלאות</b>: ברכת יוצר. ראה גם לעיל פ' בשלח קסה, א."],["9770","284","<b>שנשמות הגבוהות. . שנקראים קדושים</b>: ראה גם לעיל פ' שמות ד, ג. וש\"נ."],["9771","285","<b>ילכו מחיל אל חיל</b>: תהלים פד, ח."],["9772","286","<b>מנוחה לחיי העולמים</b>: סוף תמיד."],["9773","287","<b>אין לת\"ח מנוחה</b>: ראה גם לעיל פ' שמות שם ובהערה 204."],["9774","288","<b>חסידי[ו] הן הנשמות ועבדי[ו] הן המלאכים</b>: ראה פע\"ח (שער הזמירות) ש\"ז, פ\"ד. לעיל פ' וארא סא, ב. וש\"נ."],["9775","289","<b>קץ ושיעור</b>: חט: שיעור."],["9776","290","<b>שהנשמות נק' מהלכים</b>: ראה לעיל פ' בשלח קסד, ב. וש\"נ."],["9777","291","<b>המלאכים לפי ששרשם מקו המדה</b>: ראה גם מאמרי אדה\"א ויקרא ח\"ב ס\"ע תרסז ואילך. נ\"ך ע' תמט."],["9778","292","<b>והנה</b>: ע\"כ נמצא בתו\"ח. מכאן נדפס מו."],["9779","293","<b>פי' רביעי</b>: ראה לעיל הערה 272."],["9780","294","<b>בעדי. . מלשון הפסק</b>: נסמן לעיל תמד, ג."],["9781","295","<b>עד כאן תחום שבת</b>: ערובין נח, סע\"ב (במשנה)."],["9782","296","<b>עד ולא עד בכלל</b>: ברכות כו, ב."],["9783","297","<b>עד יעבור</b>: בשלח טו, טז."],["9784","298","<b>עד יקום גוי</b>: יהושע י, יג."],["9785","299","<b>עד כי יבא שילה</b>: ויחי מט, י."],["9786","300","<b>מעולם ועד עולם</b>: תהלים קג, יז. דהי\"א כט, י. וראה תהלים צ, ב [ושם: ומעולם עד — ראה מאמרי אדה\"א במדבר ח\"ג ע' א'קכ. דברים ח\"ג ע' א'קפב. ש\"א מב, ב. לעיל פ' שמות מח, ד]."],["9787","301","<b>ימלוך לעולם ועד</b>: בשלח טו, יח."],["9788","302","<b>כו'</b>: ח: לעולם."]]],[2300550387,"שהוא ענין וטעם א' עם פי' דעד לשון נצחיות דוקא בלי הפסק והא בהא תלי' גם ע\"פ הפשוט, כי בטעם דעד דנצחיות הנ\"ל היינו מה שא\"א לגמור כל השבח לתכליתו כלל לפי שכל מה שתוכל [להביא ו]להכיל בדעת להודות ולשבח בגדלות א\"ס ב\"ה עדיין לא הגעת אפי' לחצי שבחו מטעם הנ\"ל בענין [אמתת] דרוממות העצמות ד[א]א\"ס שאין לו שעור למעלה כלל. א\"כ בהכרח שצריך לבא לבחי' שתיקה לגמרי כמ\"ש לך<sup data-n=\"9789\">303</sup> דומיה תהלה שזהו ענין ההפסק ע\"כ ולא יותר<sup data-n=\"9790\">304</sup>, לפי שגם אם תגיע לעלוי היותר גדול ברוממות ד[א]א\"ס על כל השתלשלות דאבי\"ע עדיין לא הגעת לסיפור חצי שבח עצמו כלל, עד שא\"א להשיגו ולדבר בפה כלל מפני שלא תבא<sup data-n=\"9791\">305</sup> לאמתת אור עצמותו לעולם משום דלמתב\"כ מפני שאין לו שעור למעלה כו' (גם בחי' העוה\"ב אנו אומרים אין זולתך מלכנו לחיי העוה\"ב). וא\"כ זהו בעד כאן ולא יותר שהוא ההפסק מצד ההעלאה לאין שעור בא\"ס שנמצא יש כאן דבר והיפוכו בנושא א', שהוא כמו ענין א' וטעם<sup data-n=\"9792\">306</sup> א' דהיינו שמשובח ומפואר עד\"י ע\"ד בבחי' נצחיות ד[א]א\"ס וגם הרי הוא בבחי' ההפסק [ו]שתיקה מטעם זה עצמו וד\"ל.\n<b>אך</b> א\"כ שיש הפסק ושתיקה איך אומר יהללוך סלה<sup data-n=\"9793\">307</sup> ועד וכן משובח עדי עד ממש וכמ\"ש ילכו מחיל כו', הענין הוא דשניהם אמת שמהללים בעא\"ע בלי הפסק כלל אך זהו עצמו נק' הפסק ושעור מאחר שלא יוכל להגיע לאמתת אור עצמותו ית' לעולם גם שהולכים ועולים תמיד ממדריגה למדריגה עליונה יותר ואין הפסק להילוכם כמ\"ש יהללוך סלה וכן משובח עדי עד אבל זהו בעמידה והפסק מאחר שלא השיגו ובאו לאמתתו כו', וכמ\"ש מי ימלל גבורות ה'<sup data-n=\"9794\">308</sup> ישמיע כל תהלתו ואין הכוונה מי ימלל שלא יוכל להביא בדבור לבד אלא שלא יוכל להשיג לעולם כל תהלתו האמיתית וכמ\"ש נורא תהלות כו' (וכן מ\"ש רבות עשית<sup data-n=\"9795\">309</sup> אתה ה' נפלאותיך ומחשבותיך אלינו כו' עצמו מספר בדבור לפי שלא יוכל להשיגו לעולם כנ\"ל). ומ\"ש דוד אמתך אלקי<sup data-n=\"9796\">310</sup> היינו מה שמאיר מאמתתו בנשמתו כמו ואמת ה' לעולם<sup data-n=\"9797\">311</sup> ולא שיגיע למדת העצמות ממש דאין לו סוף ושעור כלל, ואע\"פ שבהילוך הנשמות בהילול עולים בלי שעור והפסק שבבחי' נצחיות ממש מ\"מ לא יעלו לעולם לאמתתו ית' (גם בעוה\"ב כנ\"ל), לפי שהעלי' שבלי גבול שלהם הוא גבול והפסק לגבי אמיתית דא\"ס כמו שהוא בעצמו כו'. ויובן זה מנצחיות",[["9789","303","<b>לך</b>: ה: כבפנים. חט: לו — ראה לעיל הערה 281."],["9790","304","<b>ולא יותר</b>: ח: ותו לא."],["9791","305","<b>תבא</b>: החט: תגיע."],["9792","306","<b>כמו ענין א' וטעם</b>: חט: בא מטעם."],["9793","307","<b>יהללוך סלה</b>: תהלים פד, ה."],["9794","308","<b>מי ימלל גבורות ה'</b>: תהלים קו, ב."],["9795","309","<b>רבות עשית</b>: תהלים מ, ו."],["9796","310","<b>אמתך אלקי</b>: תהלים עא, כב."],["9797","311","<b>ואמת ה' לעולם</b>: תהלים קיז, ב."]]],[2300550404,"הזמן שאין לו הפסק כמו ימלוך לעולם ועד כענין דוד מלך ישראל חי וקיים<sup data-n=\"9798\">312</sup>, שזהו עליית המל' לע\"ל שיאיר בבחי' הזמן דנוק'<sup data-n=\"9799\">313</sup> מלך ימלוך<sup data-n=\"9800\">314</sup> כו' מאור עצמות דא\"ס שלמעלה מן הזמן לגמרי וכמאמר מי איכא זקנה קמי'<sup data-n=\"9801\">315</sup> כו', ומה שנק' עתיק יומין<sup data-n=\"9802\">316</sup> לפי שהוא מקור הראשון לזו\"נ כו', עכ\"ז לא יוכל בחי' נצחיות דזמן שבמל' להגיע לאמתת הא\"ס כמו שהוא בעצמו נבדל בערך מחלקי הזמן גם מהיות מקור למקור לזמן בעש\"נ<sup data-n=\"9803\">317</sup> כו' ואע\"פ שאומרים חי וקיים לעד<sup data-n=\"9804\">318</sup> [שנאמר כי עמך מקו\"ח<sup data-n=\"9805\">319</sup> ] וכמו אין קצבה לשנותיך<sup data-n=\"9806\">320</sup> [כו'] אין זה במהו\"ע ממש [וד\"ל].\n<b>והנה</b> כל הד' פירושים הנ\"ל בעדי שהוא קישוט או עדות או הפסק ונצחית הכל עולה לענין א' להיות שמלובש בזה מבחי' עצמות אא\"ס ב\"ה שנק' סדכ\"ס דלמתב\"כ כו' בבחי' ההעלם ואין שבכתר דוקא כנ\"ל. וזהו ותרבי ותגדלי בהגדלות קומה במוחין דחו\"ב<sup data-n=\"9807\">321</sup> ומדות פב\"פ במ\"ת, ועוד יותר שתבואי בעדי עדיים שהם בחי' מקיפים עליונים דפנימיות הכתר שנק' עדיים כנ\"ל שהן ב' כתרים דנעשה ונשמע כו'. אך הנה מ\"ש ותבואי בעדי עדיים לשון רבים עדיים הרבה וגם לשון יחיד עדי עדיים שיש עדיים רבים מאד, אך יש עדי א' שהוא מקור וראש לכל העדיים ונק' עדי כל העדיים כו'. הענין הוא כידוע שיש ג' כתרים<sup data-n=\"9808\">322</sup> בכלל כתר תורה וכתר כהונה וכתר מל', כתר כהונה בקו הימין חח\"נ ושרשו בחסד שבכתר וכתר מל' בגבו' דכתר בקו השמאל בג\"ה וכתר תורה בדת\"י<sup data-n=\"9809\">323</sup> בקו האמצעי ששרשו בת\"ת דכתר והן בחי' חג\"ת דע\"י שרש הראשון דאבות<sup data-n=\"9810\">324</sup> כידוע בענין ה'<sup data-n=\"9811\">326</sup> דהגדול<sup data-n=\"9812\">325</sup> כו'. ואמנם כתר ש\"ט דמשיח הוא העולה ע\"ג כל הג' כתרים הנ\"ל, וז\"ש ישכיל עבדי<sup data-n=\"9813\">327</sup> וירום ונשא<sup data-n=\"9814\">328</sup> וגבה מאד והוא הנק' עדי עדיים. כי ג' כתרים הנ\"ל מתחלקים לכמה מדריגות בעטרות ועדיים שונים וכמו כחתן יכהן פאר<sup data-n=\"9815\">329</sup> בחי' כתר תורה שהוא עטרה [ש]עטרה לו אמו כו' במ\"ת ועטרה ונזר דכתר כהונה באהרן וכתר מל' בדוד, וכולם כלולים בישראל שנחלקו לג' כהנים ולוים וישראלים וקבלו הכל במ\"ת באמרם נעשה ונשמע. אך כש\"ט דמשיח הוא על גביהן, הוא בחי' עטרה שבכתר עצמו שלמעלה מהתחלקות עדיין בחג\"ת דג' קוין דאצי' בתורה וכהונה ומל', והוא בחי' רעדכ\"ר שבעצמות אא\"ס ששורה בבחי' מקיף ועטרה ע\"ג הראש והוא בחי' מקור וראש<sup data-n=\"9816\">330</sup> לכל העדיים דג' כתרים הנ\"ל (וזהו [אינו] בא [רק] ע\"י תשובה",[["9798","312","<b>דוד מלך ישראל חי וקיים</b>: ר\"ה כה, א. נוסח קידוש לבנה. ראה גם לעיל פ' וארא עה, ד. וש\"נ."],["9799","313","<b>הזמן דנוק'</b>: ראה שער היחוד והאמונה פ\"ז. לעיל פ' בשלח רלד, א. הערה 775."],["9800","314","<b>מלך ימלוך</b>: ראה זהר בראשית לד, א."],["9801","315","<b>מי איכא זקנה קמי'</b>: יבמות טז, ב."],["9802","316","<b>ומה שנק' עתיק יומין</b>: דניאל ז, ט. ראה גם לעיל פ' משפטים שב, א. שערי אורה כ, ב ובהערה 24."],["9803","317","<b>בעש\"נ</b>: בעולם שנה נפש."],["9804","318","<b>חי וקיים לעד</b>: ברכות לג, א."],["9805","319","<b>כי עמך מקו\"ח</b>: תהלים לו, י."],["9806","320","<b>אין קצבה לשנותיך</b>: תפלת מוסף לימים נוראים לפני קדושת כתר."],["9807","321","<b>דחו\"ב</b>: החט: דחב\"ד."],["9808","322","<b>שיש ג' כתרים</b>: ראה גם לעיל תמז, ד. וש\"נ."],["9809","323","<b>חח\"נ. . בג\"ה. . בדת\"י</b>: נסמן לעיל פ' יתרו רסט, ג הערה 19."],["9810","324","<b>חג\"ת דע\"י. . דאבות</b>: ראה גם לעיל פ' בשלח קנח, ב. וש\"נ."],["9811","326","<b>ה' דהגדול</b>: ח: האדם הגדול — יהושע יד, טו. ראה גם מאמרי אדה\"א ויקרא ח\"א ע' טו. אוה\"ת נ\"ך ח\"א ע' ד וע' תעט."],["9812","325","<b>ה' דהגדול</b>: ראה גם לעיל פ' בא קכז, ג. וש\"נ."],["9813","327","<b>דמשיח. . ישכיל עבדי</b>: נסמן לעיל פ' ויקהל שצו, ב."],["9814","328","<b>וירום ונשא</b>: כ\"ה גם בה. ח: ליתא. ט: כו'. ובישעי' נב, יג: ירום ונשא."],["9815","329","<b>כחתן יכהן פאר</b>: ישעי' סא, י."],["9816","330","<b>וראש</b>: ח: ושרש."]]],[2300550421,"דוקא שהוא בחי' או\"ח לקדמותו ממש וכמ\"ש אם ישראל עושין תשובה נגאלין<sup data-n=\"9817\">331</sup> וגם משה לא זכה לתשובה<sup data-n=\"9818\">332</sup> רק קודם מותו מפני שבאו\"ח דתשובה יאיר מרעדכ\"ר שאינו מוגבל בכלים דתומ\"צ וכנ\"ל בענין לאכפי' לס\"א<sup data-n=\"9819\">333</sup> כו' דאסתלק יקרא [כו'] וע\"כ נק' עדי עדיים כו').\n<b>והנה</b> באמת יותר נכון לפרש בפי' עדי עדיים ולא שהוא ראש לכל עדיים כנ\"ל, אלא כוונתו על ענין העליות דנשמות הקדושים שיהללוך בלי הפסק כלל לפי שאין שעור בעליות לעלות למעלה עד רום המעלות בעצמות אא\"ס בעא\"ע כמו ילכו מחיל אל חיל, ובכל עלי' זו למעלה מזו נמשך להם עדי ועטרה בראשם כמו צדיקים יושבין ועטרותיהם בראשיהם<sup data-n=\"9820\">334</sup> שהוא בחי' המקיף דרעדכ\"ר הנ\"ל כמו כצנה רצון תעטרנו וכן באור פניך כי רציתם<sup data-n=\"9821\">335</sup> כו' וכה\"ג, לפי שהעליות הן הרבה מאד זו למעלה מזו עד אין שעור כנ\"ל ע\"כ גם העדיים שלהם הם הרבה מאד, והיינו פי' בעדי עדיים הרבה עד אין שעור מטעם הנ\"ל וד\"ל. וזה הפי' יותר נכון<sup data-n=\"9822\">336</sup> בפשט הכתוב בלשון עדי עדיים, ולא כפי' הא' ראש לכל העדיים שנותן קצבה ושעור עכ\"פ לקרותו מקור לכל העדיים והוא בחי' הארת רעדכ\"ר הנ\"ל. אבל לפ\"ז מטעם העליות רבות שעולים בלי שעור והפסק כלל הרי אין קצבה ושעור כלל לרבוי העדיים (וכמו ת' עלמין דכסופין דנהרין לצדיקיא כו' או ענין ש\"י עולמות<sup data-n=\"9823\">337</sup> שהוא חצי כתר ויש בזה ג\"כ קצבה ושעור, אמנם מ\"ש ע\"פ וקוי ה' יחליפו כח כו' שעתיד לעשות כנפים לנשמות<sup data-n=\"9824\">338</sup> הצדיקים ויהיו שטים ע\"פ המים כו' שזהו העלי' עד אין שעור ממש וד\"ל).\n<b>ועם</b> כל הנ\"ל יובן בתוס' ביאור בטעם שנק' משכן העדות והוא בחי' משכן העליון דבחי' חו\"ב י\"ה כו' שזהו מפני שכל העדיים והכתרים הנ\"ל הוא בא ע\"י בטול רצון זר במצות ל\"ת שמזה נעשה שרש היחו\"ע די\"ה בבחי' ההעלם וההסתר שבאור הכתר עצמו כנ\"ל וז\"ש ותבואי בעדי עדיים כו', ע\"כ נק' משכן העדות שכולל כל הד' פירושים הנ\"ל עדות ממש ועדי וקישוט וגם לשון נצחיות והפסק מפני שהכל ענין וטעם א' כנ\"ל. וזהו ג\"כ ששם עלו שבטים שבטי י\"ה דוקא ע\"כ נעשה מזה בחי' עדות לישראל כו' ג\"כ ע\"ד הנ\"ל בפי' עדי עדיים כו' (והיינו ג\"כ ענין אלה פקודי המשכן דו\"ה הנגלות לנו שנק' עדות על",[["9817","331","<b>אם ישראל עושין תשובה נגאלין</b>: סנהדרין צז, ב. ראה לעיל פ' שמות לז, א. וש\"נ."],["9818","332","<b>משה. . זכה לתשובה</b>: נסמן לעיל פ' תצוה שמג, ד."],["9819","333","<b>לס\"א</b>: חט: (ו)לאהפכא."],["9820","334","<b>צדיקים יושבין ועטרותיהם בראשיהם</b>: ברכות יז, א."],["9821","335","<b>באור פניך כי רציתם</b>: תהלים מד, ו [ושם: ואור — ראה שערי אורה צג, ב הערה 21]."],["9822","336","<b>נכון</b>: החט: ליתא. ולעיל תמד, סע\"ג (שעליו מיוסד מאמר זה כנ\"ל) איתא: אמיתי."],["9823","337","<b>ש\"י עולמות</b>: סוף עוקצי'. ראה הקדמת הראב\"ד לס\"י (ירושלים תשכ\"ב ד, א)."],["9824","338","<b>וקוי ה' יחליפו כח. . כנפים לנשמות</b>: ישעי' מ, לא. ראה יל\"ש שם. סנהדרין צב, רע\"ב. ד\"ה זה במאמרי אדה\"א בראשית ע' עז ואילך. ע' קל ואילך."]]],[2300550437,"הנסתרות דמשכן העליון דו\"ה<sup data-n=\"9825\">339</sup> כו' דלפ\"ז מה שנק' משכן<sup data-n=\"9826\">340</sup> העדות ע\"פ ד' פירושים הנ\"ל הכל הוא בא מיחוד דו\"ה במשכן סתם שהן ב' כתרים דנעשה ונשמע (והוא כתר ש\"ט דמשיח שעולה ע\"ג ג' כתרים הנ\"ל כמ\"ש ואלה דברי דוד<sup data-n=\"9827\">341</sup> האחרונים [נאום דוד] הקים ע\"ל כו').\n<b>אשר</b> פוקד ע\"פ משה. הנה י\"ל בזה שאמר אשר פוקד כו' אם קאי ארישא אלה פקודי המשכן סתם דוקא ולא אדסמיך לי' במשכן העדות א\"כ [ל]מה צריך לכפול ולומר אשר פוקד הול\"ל אלה פקודי המשכן של משה כו', אלא צ\"ל דקאי אדסמיך לי' דוקא שהוא משכן העדות ולא על פקידה דאלה פקודי כו', כי הרי בפקידה דאלה פקודי שם מזכיר לשון רבים אלה פקודי לשון רבים דלשון אלה רבים הם שהם המדות שכלולים מוי\"ו כנ\"ל, ובמשכן העדות שהבדיל והפסיק [ב]הענין והכפיל<sup data-n=\"9828\">342</sup> לומר עליו שם משכן העדות דוקא זהו בבחי' יחידה ע\"כ עליו דוקא אמר<sup data-n=\"9829\">343</sup> אשר פוקד כו' לשון יחיד וד\"ל.\n<b>וביאור</b> הענין<sup data-n=\"9830\">344</sup>, הנה יובן ע\"פ הנ\"ל בהפרש שבין בחי' ו\"ה דתומ\"צ הנגלות לנו כו' שהן אורות בכלים מכלים שונים לנסתרות די\"ה ביחו\"ע דחו\"ב ששרשם מבחי' ההעלם שבכתר שא\"א שיתלבש בכלי כלל רק בבחי' הבטול דמ\"ה דחכ' כמו מה פשפשת כו', וכמו בלאו דל\"ת שקודם להן שאינו מושג שם רק בדרך שלילה כו', אבל בהשגה ממש א\"א להשיגו כלל שהרי נק' סדכ\"ס דלמתב\"כ [ו]נק' שכל הנעלם מכל רעיון ע\"כ אינו יכול לשכון רק בבחי' הבטול דמ\"ה דחכ'. [ו]זהו בחי' [ו]מדריגת משה שהי' בבחי' פנימיות דחכ' שנק' כח מ\"ה בבטול עצמי ותמידי בבחי' אין ממש וכמ\"ש ונחנו מ\"ה<sup data-n=\"9831\">345</sup> מ\"ה דחכ' בחי' נו\"ה<sup data-n=\"9832\">346</sup> דאבא, וע\"כ הי' משה שפל ועניו מכל האדם<sup data-n=\"9833\">347</sup> כו' שהי' בבחי' בטול במציאות כאלו אינו ממש וע\"כ הי' נשמתו בחי' כלי לאור עצמות א\"ס שנק' שושבינא דמלכא<sup data-n=\"9834\">348</sup> כמ\"ש משה ידבר<sup data-n=\"9835\">349</sup> כו' (והוא לפי שאין בחי' העלם דעצמות שורה אלא על בחי' העדר ובטול הכלי דוקא, והוא כמו בבחי' השתחואה שהוא [בחי' ה]בטול בעצם מכל וכל וכמו שמצינו בר\"ע שהי' כורע ומשתחוה בש\"ע מאד עד שאדם מניחו בזויות זו<sup data-n=\"9836\">350</sup> ומוצאו בזו כו', וההשתחואה אינה רק מבחי' העדר הכלי וביטול בתכלית כו'). וע\"כ הי' משה כבד פה<sup data-n=\"9837\">351</sup> בדבור להיותו בחי' אין דחכ' כמו שהוא בהעלם טרם שיוכל לבא מאין ליש בהשגה [ב]דבור כידוע. וזהו אשר פוקד ע\"פ משה דקאי אדסמיך לי' דוקא שהוא משכן העדות העליון דבחי' י\"ה שנק' נסתרות שאין בחי' פקידה ויחוד",[["9825","339","<b>דו\"ה</b>: חט: די\"ה."],["9826","340","<b>משכן</b>: שם: ליתא."],["9827","341","<b>ואלה דברי דוד</b>: שמו\"ב כג, א [בדילוג]."],["9828","342","<b>והכפיל</b>: חט: והתחיל."],["9829","343","<b>דוקא אמר</b>: ח: הוא שאמר. ט: דוקא הוא שאמר."],["9830","344","<b>הענין</b>: ח: הדברים."],["9831","345","<b>ונחנו מ\"ה</b>: בשלח טז, ז. ח. ראה גם לעיל פ' שמות מג, א. וש\"נ."],["9832","346","<b>נו\"ה</b>: ח: ג\"ר."],["9833","347","<b>משה שפל ועניו מכל האדם</b>: בהעלותך יב, ג. ראה גם לעיל פ' תצוה שסט, ד."],["9834","348","<b>משה. . שושבינא דמלכא</b>: נסמן לעיל בפ' יתרו רסג, ב."],["9835","349","<b>משה ידבר</b>: יתרו יט, ט."],["9836","350","<b>בר\"ע שהי' כורע. . שאדם מניחו בזויות זו</b>: ברכות לא, א."],["9837","351","<b>משה כבד פה</b>: שמות ד, י. ראה גם לעיל פ' תצוה שכג, ג. וש\"נ."]]],[2300550452,"עליון זה אלא ע\"י משה בחי' מ\"ה בעצם כמו מה שמו<sup data-n=\"9838\">352</sup> כו' מטעם הנ\"ל. וז\"ש אשר פוקד לשון יחיד ע\"י משה לבדו משא\"כ פקודי המשכן סתם שהוא יחוד דו\"ה הנגלות לנו בתומ\"צ בפו\"מ זהו נעשה ע\"י רבים שהן כנ\"י בשרשם בוי\"ו מדות דאצי' שכלול כאו\"א מוי\"ו שהוא גימ' אלה כו' וד\"ל.\n<b>והנה</b> מ\"ש רבבה כצמח השדה נתתיך כו', זהו מדבר בשעה שהיו ישראל במצרים שהיו שם בבחי' קטנות מאד כצמ\"ח השדה שה[י]א צמיחה שבקטנות כמו קטנות המדות אהוי\"ר שנולדו ע\"פ צמצום השכל שבמוח לפשע\"ד בהשגות אלקות שמצומצם בכלי המוח כו', ואח\"כ ותרבי ותגדלי כו', בחי' הגדלה זו היינו בבחי' מוחין דחו\"ב שבמדות בבחי' גדלות דאור אבא שלמעלה מבחי' ההשגה דבינה והוא בחי' ראי' עין השכל כמו שהי' במ\"ת שהי' בבחי' ראיית פב\"פ, והיינו בחי' הבטול העצמי דבחי' מ\"ה דחכ' בחי' משה הנ\"ל שהוא הבטול מצד עצמות אא\"ס שבכתר שא\"א לבא בכלי השגה דלמתב\"כ שזהו יחוד<sup data-n=\"9839\">353</sup> די\"ה משכן העדות הנ\"ל. ולפי שלא הי' בכח בנשמת[ם] להכיל ולהגיע למדריגה זו שיהי' בהם האה' ודביקות רק מצד עצמו' אא\"ס בבטול עצמ[י] דמ\"ה הנ\"ל, ע\"כ נצטוו לאכול מצה בז' ימי הפסח<sup data-n=\"9840\">354</sup> וזה הי' תחלת ההגדלה דמוחין דגדלות דאבא שהי' שלימותו במ\"ת. ואע\"פ שאמר בפע\"ח שמצה הוא בבחי' קטנות דאבא<sup data-n=\"9841\">355</sup> ונק' לחם עוני<sup data-n=\"9842\">356</sup> כו' שהוא [ה]אמונה העצמי' כו', אך מ\"מ שרשה הוא בבחי' פנימי' הבטול דכח מ\"ה דחכ' כנ\"ל רק שמתלבשת בבחי' קטנות דאמונה ונק' מיכלא דמהימנותא<sup data-n=\"9843\">357</sup> כמ\"ש בזהר, וזהו כמו התינוק שיודע ומכיר את אביו ונמשך אחריו<sup data-n=\"9844\">358</sup> בלי טעם ודעת כלל כמ\"ש במ\"א. וזהו מצות יאכל את ז' הימים<sup data-n=\"9845\">359</sup> פי' ז' הימים הם ז' המדות שנולדים מבינה אם הבנים שיומשך בהם מבחי' הגדלות דמ\"ה דחכ' והוא בחי' הבטול בעצם הנ\"ל, וכבר נעשה הכנה זו דמצות מצה בז' ימי הפסח שזהו בחי' ההמשכה דמ\"ה דחכ' בנש\"י שעי\"ז יוכלו אח\"כ להיות כלים לקבלת התורה פב\"פ בכל הכתרים הנ\"ל שנק' עדי עדיים כו' שהוא מקור כל הכתרים שנק' רעדכ\"ר או סדכ\"ס כנ\"ל. וז\"ש מצות יאכל לשון מפעיל<sup data-n=\"9846\">360</sup> שיפעיל המשכ[ת] מ\"ה דחכ' במדות כמו מאכיל לזולתו, כך יאכיל למדות מבחי' מ\"ה דח\"ע גם שהוא בקטנות עדיין אבל הרי יבא לבחי' גדלות החכ' במ\"ת כו' והוא האמונה במהו\"ע דוקא כמ\"ש במ\"א, ואח\"כ יוכלו לקבל בחי' פנימיות ועצמיות [ד]אא\"ס בי\"ה שנק' נסתרות, וז\"ש ותגדלי במצה שאכלו ז' הימים ואח\"כ ותבואי בעדי עדיים במ\"ת כו' וכנ\"ל בטעם מ\"ש משכן העדות אשר פוקד ע\"פ משה דוקא וד\"ל.",[["9838","352","<b>מה שמו</b>: שמות ג, יג."],["9839","353","<b>יחוד</b>: החט: יח\"ע."],["9840","354","<b>נצטוו לאכול מצה בז' ימי הפסח</b>: בא יב, טו. וראה לקמן הערה 359."],["9841","355","<b>שאמר בפע\"ח שמצה. . קטנות דאבא</b>: נסמן לעיל תמח, ב."],["9842","356","<b>ונק' לחם עוני</b>: פ' ראה לז, ג. ראה גם מאמרי אדה\"א ויקרא ח\"א ע' רצג, וש\"נ."],["9843","357","<b>מיכלא דמהימנותא</b>: ראה זהר (רע\"מ) בא מא, א. מאמרי אדה\"א ויקרא ח\"ב ע' תרלו. וש\"נ."],["9844","358","<b>כמו התינוק. . ונמשך אחריו</b>: ראה שה\"א יד, א."],["9845","359","<b>מצות יאכל את ז' הימים</b>: בא יג, ז. ראה גם לעיל פ' בא קכא, א. וש\"נ."],["9846","360","<b>מצות יאכל לשון מפעיל</b>: ראה לעיל תמה, א ובהערה 118."]]],[2300550467,"<b>והנה</b> כפי כל הנ\"ל בפי' אלה פקודי המשכן משכן העדות דו\"ה וי\"ה דמ\"ע ול\"ת ויח\"ת ויחו\"ע כו' אשר פוקד ע\"פ משה דוקא בחי' יחו\"ע דמשכן העדות די\"ה כו', כך ממש יובן בכל סדר התפלה בפסוד\"ז עד ק\"ש כו'. הנה ידוע דפסוק ראשון של ק\"ש העיקר הוא בבחי' יחו\"ע<sup data-n=\"9847\">361</sup> די\"ה חו\"ב דאצי' שנק' נסתרות להוי' אלקינו כנ\"ל שהוא משכן העדות כו' וכמ\"ש שמע ישראל<sup data-n=\"9848\">362</sup> ה' אלקינו שזהו י\"ה דחו\"ב דאצי' ה' אחד שם שורה מבחי' אח\"פ ממש שנק' עה\"ע סדכ\"ס כנ\"ל, ויחו\"ע זה קודם לואהבת שאח\"כ שמדבר בהתפעלות המדות אהוי\"ר שנולדים מן השכל והטעם דוקא וז\"ש ואהבת בכל לבבך<sup data-n=\"9849\">363</sup> כו' וזהו בחי' יחו\"ת דבשכמל\"ו שהוא נק' משכן סתם, והיינו מ\"ש אלה פקודי המשכן ביחוד דו\"ה בקבלת עומ\"ש באהוי\"ר בקיום תומ\"צ הנגלות לנו כו' שזהו בחי' אלה כנ\"ל וד\"ל (ולפי שפ' שמע נאמרה מפי משה לישראל מלמעלה למטה ע\"כ קדם יחו\"ע ליחו\"ת ובמעשה [ה]משכן שהוא בחי' העלא[ה ד]כנ\"י [מלמטלמ\"ע] לעשות כלים ליחו\"ע הקדים יחו\"ת ליחו\"ע שז\"ש אלה פקודי תחלה כו'). אך הנה קודם ק\"ש וברכותיה תקנו אנשי כנה\"ג לומר פסוד\"ז<sup data-n=\"9850\">364</sup> בקול רם<sup data-n=\"9851\">365</sup> כמ\"ש רוממות אל בגרונם<sup data-n=\"9852\">366</sup> כו' שהוא בחי' הכנה לק\"ש, שאם לא הקדמת פסוד\"ז א\"א לכנ\"י לבא לבחי' ומדריגת דיחו\"ע דק\"ש די\"ה כנ\"ל שהוא הוי' אלקינו שנק' נסתרות כנ\"ל, והיינו כמ\"ש אלה פקודי המשכן קודם משכן העדות כו'. דהנה ידוע דעיקר פסוד\"ז הוא בשיר ורינה דוקא כמו שיר הלוים כו' ולכך נק' פסוד\"ז, וזהו הכנה ליחו\"ע דק\"ש שע\"י השיר והזמרה תחלה יוכלו להגיע ליחו\"ע די\"ה שבק\"ש. וזה הי' עבודת הלוים בשיר כאשר נשאו את המשכן<sup data-n=\"9853\">367</sup> דכתיב ונשאו הלוים<sup data-n=\"9854\">368</sup> כו' והקימו את המשכן<sup data-n=\"9855\">369</sup> דנשיאת המשכן והקמתו הכל הי' ע\"י הלוים דוקא, להיות שרשם בבחי' גבו'<sup data-n=\"9856\">370</sup> דקדושה בהעלאה ובטול והתכללות ברשפי אש התשוקה באלקים חיים (כמרכבה עליונה שנושאת הכסא כו'), ואח\"כ היו מקימים המשכן להיות בו גילוי שכינה שיהי' נק' משכן העדות. וא\"כ בחי' שיר הלוים בנשיאתם את המשכן הי' ענין הכנה לבחי' יחו\"ע דמשכן העדות הנ\"ל וכך הוא ממש בשיר וזמרה דפסוד\"ז שהוא כשיר הלוים להיות מזה הכנה ליחו\"ע דק\"ש כנ\"ל.\n<b>ויובן</b> זה בהקדם תחלה ענין שיר הלוים שהי' כמו שיר המלאכים עליונים שבמרכבה והוא מ\"ש בהן והחיות רו\"ש כמראה הבזק<sup data-n=\"9857\">371</sup> והוא כמו הלהב היוצא מן החרסים<sup data-n=\"9858\">372</sup>",[["9847","361","<b>דפסוק ראשון. . יחו\"ע</b>: זהר בראשית יח, ב."],["9848","362","<b>שמע ישראל</b>: ואתחנן ו, ד."],["9849","363","<b>ואהבת בכל לבבך</b>: ואתחנן ו, ה [בדילוג]."],["9850","364","<b>תקנו אנשי כנה\"ג לומר פסוד\"ז</b>: ראה לעיל תמה, א הערה 122."],["9851","365","<b>פסוד\"ז בקול רם</b>: ראה גם לעיל פ' תרומה שט, ב. וש\"נ."],["9852","366","<b>רוממות אל בגרונם</b>: תהלים קמט, ו."],["9853","367","<b>עבודת הלוים בשיר כאשר נשאו את המשכן</b>: ראה גם להלן בפנים. מאמרי אדה\"א שמות ח\"ב ע' תקמו. וראה גם דהי\"א טו, טז ואילך (בנשיאת הארון). ערכין יא, סע\"א (הפסוקים). וראה גם לעיל תמה, ב. לקו\"ת פקודי ה, ג."],["9854","368","<b>ונשאו הלוים</b>: נסמן לעיל תמה, א הערה 124."],["9855","369","<b>והקימו את המשכן</b>: בהעלותך י, כא."],["9856","370","<b>הלוים. . שרשם בבחי' גבו'</b>: ראה גם לעיל פ' וארא פה, ד."],["9857","371","<b>והחיות רו\"ש כמראה הבזק</b>: יחזקאל א, יד."],["9858","372","<b>הלהב היוצא מן החרסים</b>: ראה חגיגה יג, ב וברש\"י שם. מאמרי אדה\"א קונטרסים ס\"ע תלט ואילך."]]],[2300550482,"שעולה למעלה וחוזר ויורד ונכנס וחוזר ועולה כידוע, וכך הוא ברו\"ש דמלאכים שעולה ויורד בתמידות אחר הרצוא שוב ואחר השוב רצוא כאור הנר שמתנענע בתמידות בבחי' עלי' וירידה בתמידות (שנק' או\"ח ואו\"י יחד כמו ב' דפיקות שבלב שהחיות עולה ומסתלק בדפיקו הא' בבחי' רצוא ומיד חוזר ונמשך בלב בבחי' שוב וההסתלקות הוא עיקר החיות שנמשך אח\"כ (וכמו הנר שהסתלקות של האור למקורו הוא סיבת המשכתו להאיר בפתילה). וכך הוא בנר הוי' נשמת אדם<sup data-n=\"9859\">373</sup> שהוא בבחי' רו\"ש כמלאכים מאחר שנק' נר הוי' ממש, והוא מה שנראה לעין שטבע הנשמה האלקית להיות בה בחי' ההסתלקות והתשוקה ליכלל באלקים חיים מקור האמיתי כמ\"ש כי רוח האדם הוא עולה למעלה<sup data-n=\"9860\">374</sup> תמיד כו', ואח\"כ מיד חוזר ונמשך הארת אור אלקי בנשמה בבחי' שוב והוא בחי' אה' [ה]עליונה שנמשכה על הנשמה להאירה ולהחיותה בחיות האלקי מחדש. וזהו ב' מיני התפעלות הנשמה באה' אלקי' א' בבחי' או\"ח וכמו נכספה וגם כלתה נפשי<sup data-n=\"9861\">375</sup> צמאה לך נפשי<sup data-n=\"9862\">376</sup> כמה לך בשרי וכה\"ג, וזה ימצא כל אדם בנפשו בכל עת מצוא שתכסוף מאד נפשו להתדבק באמת ביוצרה בכל לב בשר<sup data-n=\"9863\">377</sup> ורוח אייתי רוח<sup data-n=\"9864\">378</sup> כו' שמעורר וממשיך על נפשו אה\"ר עליונה כמ\"ש אהבת עולם אהבתיך<sup data-n=\"9865\">379</sup> ע\"כ משכתיך חסד כו', והוא מ\"ה שחפץ האדם בקרבת אלקים שיהי' בנפשו גלוי אלקות בתוס' מלמעלה למטה כמו שמבקשים והאר עינינו<sup data-n=\"9866\">380</sup> כידוע. וזהו בחי' רו\"ש דנשמה בתמידות אחר רצוא שוב ואחר שוב רצוא והוא חדוה ומרירות יחד זע\"ז כמו בכי' תק[י]עה בלבאי<sup data-n=\"9867\">381</sup> מסט' דא וחדוה מסט' דא כידוע) (וכמו כל הלבבות יראוך<sup data-n=\"9868\">382</sup> וכל קרב וכליות יזמרו לשמך יראה מבפנים וזמרה מבחוץ וכמ\"ש במקום גילה שם תהא רעדה<sup data-n=\"9869\">383</sup> כו' וכה\"ג) וכן חוזר חלילה בתמידות, וע\"כ באופן עליות וירידות כזאת תוכל הנשמה לעלות בעא\"ע כמו ילכו מחיל אל חיל (וכמו בשתים יעופף<sup data-n=\"9870\">384</sup> כו') עד רום המעלות כמו יהללוך סלה בלי הפסק כו' כנ\"ל בענין משובח ומפואר עדי עד כו'. וזהו כל עיקר ענין מספר ימי האדם שניתן לו בכל יום לחדש אור חיות נשמתו בהתפעלות דרו\"ש (שפלות בלב נשבר ושמחה תשועה<sup data-n=\"9871\">385</sup> והמשכת אלקות אהוי\"ר כו' וכנ\"ל) להעלותה [ב]מקורה שתהי' צרורה בצרור החיים את ה' ממש וד\"ל.\n<b>והנה</b> כך ממש הי' ענין עבודת הלוים בשיר וזמרה על הקרבן<sup data-n=\"9872\">386</sup> וכן כשהיו נושאין המשכן הי' בהתלהבות",[["9859","373","<b>בנר הוי' נשמת אדם</b>: משלי כ, כז."],["9860","374","<b>כי רוח האדם הוא עולה למעלה</b>: נסמן לעיל פ' יתרו רנא, ג."],["9861","375","<b>נכספה וגם כלתה נפשי</b>: תהלים פד, ג."],["9862","376","<b>צמאה לך נפשי</b>: תהלים סג, ב."],["9863","377","<b>בשר</b>: ה: כבפנים. חט: כו'."],["9864","378","<b>ורוח אייתי רוח</b>: נסמן לעיל בפ' יתרו רנא, א."],["9865","379","<b>אהבת עולם אהבתיך</b>: ירמי' לא, ב [ושם: ואהבת — נסמן לעיל פ' וארא סב, ג הערה 131]."],["9866","380","<b>והאר עינינו </b>[ח ניתוסף: בתורתך. ט ניתוסף: כו']: נוסח ברכת ק\"ש."],["9867","381","<b>בכי' תק[י]עה בלבאי</b>: נסמן לעיל בפ' תצוה שכב, ד הערה 175."],["9868","382","<b>כל הלבבות יראוך</b>: ראה גם לעיל שם שנב, ד. וש\"נ."],["9869","383","<b>במקום גילה שם תהא רעדה</b>: ראה גם לעיל שכב, ד ובהערה 167."],["9870","384","<b>בשתים יעופף</b>: ישעי' ו, ב [ושם: ובשתים — נסמן לעיל פ' בשלח קסד, ג הערה 25]."],["9871","385","<b>תשועה</b>: החט: תשוקה."],["9872","386","<b>בשיר וזמרה על הקרבן</b>: ראה ר\"ה ל, ב ואילך. לעיל פ' בא קו, ד. וש\"נ."]]],[2300550497,"רשפי אש התשוקה [ה]אלק[י]ת ליכלל באלקים חיים בבחי' גבו' דרו\"ש כמלאכים וחיות הקדש שהן ברו\"ש תמיד כנ\"ל, וע\"כ היו מגביהים ומרוממים ומנשאים למשכן שהוא השכינה למעלה מעלה והוא בחי' יחו\"ע דחו\"ב דאצי' להיות בבחי' משכן העדות דוקא כנ\"ל וכמ\"ש ויהי בנסוע כו'<sup data-n=\"9873\">387</sup> ויאמר משה קומה ה' כו' ובנחה יאמר שובה<sup data-n=\"9874\">388</sup> כו' ולפ\"ע העלי' בנושאי המשכן (כמרכבה שנושאות ומנושאות<sup data-n=\"9875\">389</sup> כך ארון נושאיו נשא<sup data-n=\"9876\">390</sup> כמ\"ש במ\"א). וכך הוא ממש ענין פסוד\"ז לפני ק\"ש שהוא ענין הכנה לרומם את הנשמה אלקית ולהעלותה למעלה באופן שתוכל לייחד יחו\"ע די\"ה באמרו הוי' אלקינו ה' אחד אח\"פ בחי' עה\"ע סדכ\"ס הנ\"ל בפסוק ראשון הנ\"ל שזהו בחי' משכן העדות אשר פוקד ע\"פ משה דוקא כנ\"ל וד\"ל. וזהו ששם עלו שבטים שבטי י\"ה ביחו\"ע דחו\"ב דאצי' ששם שורה מעצמות אא\"ס שבכת\"ר כנ\"ל, עדות לישראל עדות על הנסתרות הללו, להודות לשם הוי' בב' מדריגות דאו\"ח ואו\"י הנ\"ל מלמטה למעלה ומלמעלה למטה בחי' רו\"ש הנ\"ל. כי יש ב' הודיות ב' דפיקות<sup data-n=\"9877\">391</sup> הנ\"ל מלמטה למעלה כמו הפעם אודה את ה'<sup data-n=\"9878\">392</sup> כו' והוא לשם הוי' דפנימי' אור הכתר בחכ' בחי' מ\"ה דחכ', ומלמעלה למטה שנמשך לשם הוי' בחי' שוב שהן ו\"ה הנגלות לנו בתומ\"צ כו' וד\"ל.\n<b>וזהו</b> אשר פוקד ע\"פ משה עבודת הלוים ביד איתמר בן אהרן הכהן, דהנה כל עיקר עבודת הלוים הי' רק לנשאות את המשכן שהוא לרוממו ולהעלותו (כמו מרכבה עליונה שנק' רוממי שדי<sup data-n=\"9879\">393</sup> ), וזהו ונשאו את המשכן<sup data-n=\"9880\">394</sup> וגם הקימו את המשכן כו'. והנה משמעות הפשוט בפשט הכתוב הזה במ\"ש אשר פוקד ע\"פ משה עבודת הלוים כו' שע\"פ משה פוקד גם עבודת הלוים וקאי אדסמיך לי' וגם על שלאחריו וה\"ק אלה פקודי המשכן אשר פוקד ע\"פ משה משכן העדות וגם עבודת הלוים שעל שניהם אמר אשר פוקד ע\"פ משה דוקא, ומ\"ש עוד ביד איתמר זהו ענין שלישי בפ\"ע שעבודת הלוים הי' ביד איתמר דוקא (כמשי\"ת). ולפ\"ז י\"ל מה שייכות עבודת הלוים שגם זה הוא ע\"פ משה דוקא שהוא בחי' מ\"ה דחכ' דוקא כו'. אך הנה הענין הוא כי כמו שמשכן העדות יחוד עליון די\"ה כנ\"ל פוקד ע\"פ משה דוקא מטעם הנ\"ל כך גם עבודת הלוים בנשיאת המשכן והקמתו בבחי' רו\"ש הי' ג\"כ ע\"י פקידה דמשה דוקא.\n<b>ותחלה</b> יש להקדים שרש ענין אשר פקד פקד אותיות דפק<sup data-n=\"9881\">395</sup> והוא בחי' אחורים דאבא<sup data-n=\"9882\">396</sup> כמבואר בסה\"ק בענין",[["9873","387","<b>ויהי בנסוע כו' </b>[חט: הארון]: בהעלותך י, לה."],["9874","388","<b>ובנחה יאמר שובה</b>: בהעלותך שם, לו."],["9875","389","<b>שנושאות ומנושאות</b>: נסמן לעיל תמח, א. ראה מאמרי אדה\"ז תקס\"ד ע' כג ואילך. תו\"ח ח\"ש קל, ג. שער האמונה ע, א. מאמרי אדה\"א במדבר ח\"ב ע' שסה ואילך. ח\"ג ע' תתצט. ע' תתקכ ואילך."],["9876","390","<b>ארון נושאיו נשא</b>: ראה סוטה לה, א. מאמרי אדה\"א בראשית ע' שעג. וש\"נ."],["9877","391","<b>דפיקות</b>: ח: הפכים. גט: הפירושי\"ם."],["9878","392","<b>הפעם אודה את ה'</b>: ויצא כט, לה."],["9879","393","<b>רוממי שדי</b>: ברכת יוצר. ראה גם לעיל פ' בשלח קעט, ב. וש\"נ."],["9880","394","<b>ונשאו את המשכן</b>: נסמן לעיל תמה, ב הערה 133."],["9881","395","<b>פקד אותיות דפק</b>: נסמן לעיל תמה, ב."],["9882","396","<b>דפק. . אחורים דאבא</b>: ראה טעמי המצות להאריז\"ל פ' וירא."]]],[2300550511,"הדפק שהוא באחורים דחכ' (דאדם א' דחכ' שורה בדם<sup data-n=\"9883\">397</sup> הוא הנפש<sup data-n=\"9884\">398</sup> דבינה<sup data-n=\"9885\">399</sup> והוא הדפק כמשי\"ת) וכמו קול דודי דופק<sup data-n=\"9886\">400</sup>. והענין הוא שאנו רואים שיש בדפק שביד [ענין] עליות וירידות שהוא הסתלקות והתפשטות בבחי' רו\"ש כנ\"ל, והוא מה שהחיות שבדם עולה בהסתלקות ויוצא בדפיקו הא' ומיד בדפיקו הב' חוזר החיות ונמשך בדם כי רוחניות החיות שבדם עולה ויורד בו ברו\"ש שהן באין זה אחר זה בתמידות כמו הנשימה שברוח החיים שבלב שעולה ויורד בב' דפיקות בבחי' רו\"ש, רק שזהו בבחי' פנימיות החיות רוחני שבלב וביד נרגש בדפק בגשמיות העלאה והמשכה זו בתמידות (וכמ\"כ בנשימה שבחוטם אלא ששם ההמשכה קודם להעלאה שהוא בבחי' מול\"מ כמ\"ש במ\"א לפי שהנשמה היא במוח ונק' משפיע ללב ורוח שבלב בחי' מקבל מנשמה שבמוח כו'). ושרש ענין הדפיקה הזה בא מבחי' ח[י]צוני' ואחורים דחכ' שבנפש שבא ומתלבש בדם הוא הנפש שהוא בחי' התפשטות החיות שנמשך בגוף מחלל השמאלי ששרשו ממוח בינה<sup data-n=\"9887\">401</sup> שהוא חם ויבש<sup data-n=\"9888\">402</sup> בבחי' גבו' דאימא<sup data-n=\"9889\">403</sup>, וא' דאדם הוא כח רוחני דאור החכ' ששוכן בדם בבחי' העלם שהוא בחי' עלי' והסתלקות והוא שרש דפק שביד ברו\"ש דוקא. וע\"כ גם הדם המתפשט בשס\"ה גידין יש בהן עלי' וירידה מלמעלה למטה ומלמטה למעלה בסיבוב הילוך הדמים, וגם יש בעצם החיות שבהן הסתלקות והתפשטות<sup data-n=\"9890\">404</sup> שהחיות הנעלם עולה ומסתלק בבחי' בטול [בכח ה]רוחני דחכ' שבחלל הימיני ועי\"ז חוזר ונמשך מרוח דחכ' לדם שבחלל השמאלי שזהו יחוד דרוח ונפש כמ\"ש במ\"א (וראי' מענין הנגעים שהוא ע\"י הסתלקות אור אבא וכמ\"ש בזהר בענין הצרעת שהוא סגירו דנהורא עילאה<sup data-n=\"9891\">405</sup> דחכ' שהוא הסתלקות הא' מד\"ם אז ממילא נעשה קלקול בדם הוא הנפש דבינה וז\"ש אדם כי יהי'<sup data-n=\"9892\">406</sup> כו' כידוע). ואם לא העלאה ובטול היש לאין מדם הוא הנפש בשס\"ה גידין אין המשכה מאין דחכ' ליש דבינה שהוא בחי' הגבו' שבדם שמתפשטים אח\"כ להחיות כל הגוף, אך כ\"ז נמשך רק מחצוניות ואחורים דחכ' בבינה וד\"ל.\n<b>והדוגמא</b> מכ\"ז יובן ג\"כ למעלה בבחי' רו\"ש בשיר הלוים להיות ששרשם הוא בבחי' הגבו' עליונות דבינה כנ\"ל וע\"כ הי' עיקר עבודתם בשיר וזמרה בהעלאה דבחי' רצוא דוקא, כמו שיש בדם הוא הנפש ענין חיות שעולה ויורד בתמידות כו' כן הי' עבודת הלוים לנשאות המשכן בהעלאה והגבהה למעלה ע\"י הבטול והסתלקות ברו\"ש כמ\"ש ועבד הלוי הוא<sup data-n=\"9893\">407</sup> כו'",[["9883","397","<b>דאדם א'. . בדם</b>: ראה מבוא שערים ש\"ה, ח\"ב פ\"ה. לעיל פ' וארא עב, ד הערה 22."],["9884","398","<b>בדם הוא הנפש</b>: פ' ראה יב, כג."],["9885","399","<b>א' דחכ'. . בדם. . דבינה</b>: ראה גם לעיל פ' תצוה שנג, א. מאמרי אדה\"ז תקס\"ז ע' קפג. מאמרי אדה\"א ויקרא ח\"ב ע' תעג ואילך. במדבר ח\"ג ע' א'ריט."],["9886","400","<b>קול דודי דופק</b>: שה\"ש ה, ב. ראה גם לעיל פ' בא קד, ג הערה 374."],["9887","401","<b>בדם. . בינה</b>: ראה פרדס (שער עה\"כ) מערכת דם."],["9888","402","<b>ממוח בינה שהוא חם ויבש</b>: ראה גם לעיל פ' שמות כז, ג. וש\"נ."],["9889","403","<b>בדם. . בבחי' גבו' דאימא</b>: ראה גם מאמרי אדה\"א קונטרסים ע' תקמ. לעיל תמו, ד. וש\"נ."],["9890","404","<b>החיות שבהן הסתלקות והתפשטות</b>: ראה גם מאמרי אדה\"א דברים ח\"ג ע' תת. קונטרסים ע' תמ."],["9891","405","<b>הצרעת שהוא סגירו דנהורא עילאה</b>: נסמן לעיל פ' תצוה שנג, א."],["9892","406","<b>אדם כי יהי'</b>: תזריע יג, ב. ראה גם מאמרי אדה\"א ויקרא ח\"ב ע' תעד. קונטרסים שם."],["9893","407","<b>ועבד הלוי הוא</b>: ראה גם לעיל פ' בא קו, ד. וש\"נ."]]],[2300550525,"כמ\"ש בזהר, ועי\"ז נמשך מבחי' אור אבא באימא שזהו בחי' שוב שהוא המשכה דמ\"ה דחכ' מאין ליש כדוגמת דפק שהוא שם קפ\"ד [מ]אחורים דאבא שזהו ענין קול דודי דופק כו', ונמצא שבעבודת הלוים בנשיאת המשכן והקמתו הי' בחי' יחו\"ע די\"ה שהן חו\"ב דאצי' בבחי' פנימיות כמו שיש יחוד כזה בדפק בחצוניות. וז\"ש אשר פקד ע\"פ משה, פקד הוא בחי' פנימיות דדפק והוא בחי' פנימיות דאור אבא שזהו בחי' מ\"ה דמשה ולכך אמר [אשר] פקד ע\"פ מש\"ה דוקא, וקאי גם על עבודת הלוים דגם שעבודתם הוא ברו\"ש דחכ' בבינה בבחי' חצוניות דאדם א' ד\"ם כנ\"ל, מ\"מ כמו שיחו\"ע הפנימיות דאו\"א במשכן העדות הוא ע\"פ משה<sup data-n=\"9894\">408</sup> דוקא כך הוא בעבודת הלוים ג\"כ כו' וד\"ל.\n<b>וטעם</b> הדברים הנה ידוע דעיקר העבודה בנשיאת המשכן הי' בבני קהת שנשאו את הארון שנאמר בהם עבודת הקדש עליהם בכתף ישאו<sup data-n=\"9895\">409</sup> כו' שגם בחי' הכתפים שהוא אחורים דחכ'<sup data-n=\"9896\">410</sup> שוה עם בחי' הפנימיות לפי שהארון הוא בבחי' הכת\"ר<sup data-n=\"9897\">411</sup> עצמו כו' שזהו כמו לוחות הראשונות שמשני עבריהן היו כתובים<sup data-n=\"9898\">412</sup>. ואע\"פ שאמר בתורה שהיא כתובה פנים ואחור<sup data-n=\"9899\">413</sup> ובפנימיות התורה אמר ארוכה מארץ מדה ורחבה<sup data-n=\"9900\">414</sup> כו' ובחצוניות שבה ניתנה בגבול ושעור<sup data-n=\"9901\">415</sup> דוקא, ועכ\"ז בחי' החצוניות הנגלות לנו הוא כלי להחזיק כח הפנימיות הבלתי מוגבל משום דנובלות חכ' של מעלה<sup data-n=\"9902\">416</sup> דתורה שבא בעה\"ד לברר יש לה שרש עליון יותר גם מהפנימי' דח\"ע דתורה וכמ\"ש במ\"א ע\"פ חכמות בחוץ<sup data-n=\"9903\">417</sup> כו'. ויובן מזה גם כאן בעבודת הלוים ברו\"ש שהן אהוי\"ר כללות [כל] המ\"ע ול\"ת שבתורה הנגלות לנו הגם שזהו בחי' אחורים דאו\"א<sup data-n=\"9904\">418</sup> בחי' דפ\"ק אחורים דפקד<sup data-n=\"9905\">419</sup> כו' שזהו אדם א' ד\"ם כנ\"ל, מ\"מ אדרבה יש בחצוניות שרש עליון יותר מפנימי' היחו\"ע דאו\"א דפק\"ד<sup data-n=\"9906\">420</sup> כו' מטעם הנ\"ל במה שיש כח בחצוניות הכלים דתומ\"צ להכיל כל הפנימיות דתורה שלא יכילנה ארץ ויש<sup data-n=\"9907\">421</sup> ב' ההי\"ן ה\"א עלאה [ים] עלמא דאתכסי' וארץ עלמא<sup data-n=\"9908\">423</sup> דאתגלי'<sup data-n=\"9909\">422</sup>, והתורה הנגלית באה בארץ דוקא כמ\"ש והארץ האירה מכבודו<sup data-n=\"9910\">424</sup> אין כבוד אלא תורה<sup data-n=\"9911\">425</sup> וכמ\"ש לא בשמים היא<sup data-n=\"9912\">426</sup> ולא מעבר לים היא<sup data-n=\"9913\">427</sup> כו' וד\"ל.\n<b>וראי'</b> לזה הוא מה שמצינו שיש יתרון מעלה בתושבע\"פ יותר מתושב\"כ משום דבינה יתירה ניתנה באשה<sup data-n=\"9914\">428</sup> כו', וכך",[["9894","408","<b>דוקא. . משה</b>: חט: ליתא. וכנראה נשמט מפני תיבות הדומות: משה דוקא. . משה דוקא."],["9895","409","<b>עבודת הקדש עליהם בכתף ישאו</b>: נשא ז, ט. ראה גם ד\"ה דוד זמירות (קו\"א לתניא קסא, א). מאמרי אדה\"א בראשית ע' תסז. במדבר ח\"ב ע' תקנז."],["9896","410","<b>הכתפים שהוא אחורים דחכ'</b>: ראה גם מאמרי אדה\"א דרושי חתונה ח\"ב ע' תפה, וש\"נ. בהערה שלפנ\"ז."],["9897","411","<b>שהארון. . הכת\"ר</b>: נסמן לעיל פ' תרומה שז, ג הערה 164."],["9898","412","<b>לוחות הראשונות. . כתובים</b>: תשא לב, טו. ראה גם לעיל פ' בשלח ריב, א. וש\"נ."],["9899","413","<b>בתורה שהיא כתובה פנים ואחור</b>: יחזקאל ב, י."],["9900","414","<b>ובפנימיות התורה אמר ארוכה מארץ מדה ורחבה</b>: איוב יא, ט. ראה גם סידור שער הציצית ה, ד. אמרי בינה שער הציצית פג, ג. שער האמונה פט, א. תו\"ח לך צג, ג. וישב רא, ד. מקץ רכח, ב."],["9901","415","<b>ובחצוניות. . בגבול ושעור</b>: ראה הל' ת\"ת לאדה\"ז פ\"א ס\"ה. רפ\"ג. שם, ס\"ז."],["9902","416","<b>דנובלות חכ' של מעלה</b>: ב\"ר פי\"ז, ה. פמ\"ד, יז."],["9903","417","<b>חכמות בחוץ</b>: ראה גם לעיל פ' יתרו רסו, ד ואילך. וש\"נ."],["9904","418","<b>דאו\"א</b>: ח: דאבא."],["9905","419","<b>דפקד</b>: חט: דקפ\"ד."],["9906","420","<b>דפק\"ד</b>: שם: דקפ\"ד."],["9907","421","<b>ויש</b>: החט: וים."],["9908","423","<b>עלמא דאתכסי'. . עלמא דאתגלי'</b>: נסמן לעיל פ' תצוה שנו, ד הערה 37."],["9909","422","<b>ארץ. . [ים] עלמא דאתכסי' וארץ עלמא דאתגלי'</b>: ראה גם לעיל פ' בשלח קלח, ג. וש\"נ."],["9910","424","<b>והארץ האירה מכבודו</b>: יחזקאל מג, ב."],["9911","425","<b>אין כבוד אלא תורה</b>: אבות פ\"ו, ג [ושם: ואין]."],["9912","426","<b>לא בשמים היא</b>: נצבים ל, יב."],["9913","427","<b>ולא מעבר לים היא</b>: נצבים ל, יג."],["9914","428","<b>דבינה יתירה ניתנה באשה</b>: ראה נדה מה, ב. לעיל פ' שמות י, ב. וש\"נ."]]],[2300550538,"הוא ג\"כ בענין אדם א' ד\"ם דאע\"פ שהדפק הוא בחי' רו\"ש דהיינו מאין [דחכ'] ליש דבינה כנ\"ל זהו מצד דחכ' דא' משפיע לבינה שהוא ד\"ם ויש כאן בטול היש לאין והמשכה מאין ליש, וגם זהו בב' מדריגות בחצוניות ופנימיות כנ\"ל בענין דפק ופקד כו'. ואמנם באמת<sup data-n=\"9915\">429</sup> כ\"ז דבחי' רו\"ש הסתלקות והתפשטות לא שייך רק ביחוד דחו\"ב שהוא א' ד\"ם שהוא התלבשות דחכ' בדפק, אבל כשכבר נתפס אור החיות בדם הוא הנפש הרי אין כאן רק בחי' התפשטות לבד ולא בחי' הסתלקות כלל, והיינו ענין דם המתפשט בשס\"ה גידין בסיבוב והילוך תמידי מלמעלה למטה ומלמטה למעלה שהוא עיקר המחי' לכל האברים שנאמר בו כי הדם הוא הנפש החיונית המחי' שאין בו בחי' הסתלקות כלל רק התפשטות בבחי' יש בלבד, רק ע\"י בחי' הארת אור החכ' בדם<sup data-n=\"9916\">430</sup> נעשה בדם [ב]גידין שבו ענין הדפק כו' וד\"ל. וכך יובן למעלה<sup data-n=\"9917\">431</sup> שחצוניות תומ\"צ הוא בבחי' התפשטות יש, למעלה מרו\"ש דדפק דחכ' בחצוניות וגם בפנימיות [היחוד] דחו\"ב, אך עתה אמר אשר פקד ע\"פ משה דוקא יחו\"ע דפנימיות דחו\"ב דהיינו משכן העדות וגם עבודת הלוים בחיצוניות דרו\"ש דדפק ויחדיו יהיו תמים<sup data-n=\"9918\">432</sup> והיו לאחדים<sup data-n=\"9919\">433</sup> כמ\"ש והי'<sup data-n=\"9920\">434</sup> כו' וכמ\"ש קול דודי דופק כו', וזהו בכתף ישאו למהוי אחד באחד<sup data-n=\"9921\">435</sup> וזה א\"א כ\"א ע\"י משה שהוא שם מ\"ה מלגאו<sup data-n=\"9922\">436</sup> כו' ולכך לא נזכר אהרן ג\"כ וד\"ל.\n<b>ביד</b> איתמר בן אהרן הנה באמת יש להפליא בזה דאם אהרן עצמו לא נזכר עם משה במ\"ש אלה פקודי כו' רק אמר אשר פקד ע\"פ משה לבדו ואיך אמר בעבודת הלוים ביד איתמר בן אהרן, ומבואר למעלה דפקד זה קאי [על] גם עבודת הלוים שלאחריו כנ\"ל. אך הנה מבואר למעלה בענין פק\"ד ודפ\"ק שזהו שרש [ל]בחי' רו\"ש דעבודת הלוים בשיר לנשאות את המשכן העליון והתחתון, והוא בחי' יחוד [יחו\"ע] די\"ה ע\"י מצות ל\"ת דלאו קודם להן [ויחו\"ת] דמ\"ע בו\"ה שעל שניהם אמר קול דודי דופק כו' ששניהם שו[ים] פנימי' וחצוני' הכל פקד ע\"פ משה כו', אך כ\"ז הוא בבחי' רו\"ש ברוחניות בלבד כמו בשיר הלוים באהוי\"ר שבלב וכ\"ש ביחוד עליון די\"ה בחו\"ב מאין ליש כו'. אמנם אין זה עיקר [ותכלית] הכוונה של עצמות א\"ס ב\"ה שנתאוה להיות לו דירה בתחתונים ודירה זו ענין השראה ומנוחה ולא רו\"ש לבד, ואע\"פ שעיקר גלוי המשכת החיות אלקי",[["9915","429","<b>באמת</b>: חט: ליתא."],["9916","430","<b>בדם</b>: שם: בבינה."],["9917","431","<b>למעלה</b>: החט: לע\"ל."],["9918","432","<b>ויחדיו יהיו תמים</b>: לשון הכתוב תרומה כו, כד. ויקהל לו, כט."],["9919","433","<b>והיו לאחדים</b>: לשון הכתוב יחזקאל לז, יז."],["9920","434","<b>והי'</b>: ג: יהי'. ה: והיו. ח: ה'. ט: יהי' ה'."],["9921","435","<b>למהוי אחד באחד</b>: נסמן לעיל פ' ויקהל תה, ה."],["9922","436","<b>שם מ\"ה מלגאו</b>: נסמן לעיל פ' תצוה שלה, ג."]]],[2300550551,"אינו בא רק ע\"י רו\"ש דחו\"ב ומדות אהוי\"ר שבלב שהן ב' מיני משכן הנ\"ל, מ\"מ גם לבחי' רו\"ש זה צריך שיומשך בבחי' כלי מחזיק לאור זה שהוא יהי' כלי אל בחי' הבטול הזה דרו\"ש בתמידות דוקא כמ\"ש והחיות רו\"ש כמראה הבזק שהוא כמו להב היוצא מן החרסית, הרי יש עכ\"פ בחי' כלי שהוא החרסית שהלהב עולה ויורד בו וא\"א שיהי' להם רו\"ש בלי כלי שיאחז בו האור כו'. וכך הוא באור הנשמה האלקית שיש בה בחי' רו\"ש בתמידות כמו אור הנר שהלהב עולה ויורד בתמידות כך נר הוי' נשמת אדם יש בה בחי' רו\"ש באהוי\"ר בתמידות כנ\"ל, אך צ\"ל בחי' כלי לרו\"ש זה שהוא או\"י ואו\"ח שבה ובלי כלי לזה האור העולה ברו\"ש לא נק' נשמת אדם כלל, שהרי אמר נר הוי' דוקא נשמת אדם כנר שהוא הכלי לאור שעולה ויורד בה כו' ואז נק' נשמת אדם לשון נשימה שהוא [ב]בחי' הסתלקות והתפשטות באף כמ\"ש ויפח באפיו נ\"ח<sup data-n=\"9923\">437</sup> כו', כמו שהדפק הוא ברו\"ש בלב ובדם שביד כו'.\n<b>והנה</b> עיקר כלי לזה לבחי' הנשימה שבנשמה [ה]אלקית הוא בחכ' שבתורה דוקא כידוע בשרש בחי' נר\"נ דאדם דנפש בכבד ורוח חיים במדות שבלב בדפיקו דליבא ומשכן הנשמה הוא במוח דוקא והוא בבחי' החכ' שבמוח<sup data-n=\"9924\">438</sup> כידוע, ובחי' הכלי לאור דרו\"ש דנשמה שבמוח הוא ענין הדבור בד\"ת דוקא לפי שאין כלי המיוחד לרו\"ש דחכ' שבנשמה אלא בדבור בד\"ת בלבד וכמ\"ש חיים הם למוצאיהם בפה<sup data-n=\"9925\">439</sup> דוקא וכמ\"ש למען תהי' תורת ה' בפיך<sup data-n=\"9926\">440</sup> כו' דוקא, וכן כתיב [כי] לא על הלחם לבדו כו' כי על כל מוצא פי הוי' בד\"ת<sup data-n=\"9927\">441</sup> דוקא יחי' האדם שהוא הנשמה אלקית כמ\"ש כי הוא חייך<sup data-n=\"9928\">442</sup> ממש וכתיב כי אמרתך חייתני<sup data-n=\"9929\">443</sup> אמרתך בדבור בפה דוקא. וראי' לזה ממ\"ש בפ' ק\"ש ואהבת בכל לבבך שזהו בחי' רו\"ש דאהוי\"ר דואהבת [גימ'] ב\"פ אור<sup data-n=\"9930\">444</sup> או\"י ואו\"ח, ואח\"כ אמר והיו הדברים<sup data-n=\"9931\">445</sup> [כו'] ודברת בם<sup data-n=\"9932\">446</sup> כו' בדבור בד\"ת דוקא מפני שזהו [עיקר] הכלי לרו\"ש כנ\"ל (לפי שמהבל הדבור בד\"ת נעשה או\"מ<sup data-n=\"9933\">447</sup> לנשמה בשרשה הראשון שהוא אותיות התורה שם<sup data-n=\"9934\">448</sup> כמו שהן למעלה שנק' שמותיו העצמים [ממש], כידוע דאורייתא סתים וגלי' [וקוב\"ה סתים וגליא וכך ישראל דמתקשראן באורייתא בסתים וגליא] כמ\"ש הנסתרות כו' והנגלות לנו היינו כמו שס\"ר אותיות התורה<sup data-n=\"9935\">449</sup> בשרשן בעצמות [א]א\"ס ממש בבחי' סדכ\"ס הנ\"ל נמשך או\"מ להקיף לנשמות. וז\"ש ואשים דברי בפיך<sup data-n=\"9936\">450</sup> דברי ממש ובצל ידי כסיתיך שהקב\"ה יושב ושונה כנגדו שנאמר ה' צלך<sup data-n=\"9937\">451</sup> כו' וע\"כ על כל מוצא פי הוי' דד\"ת באדם יחי'",[["9923","437","<b>ויפח באפיו נ\"ח</b>: בראשית ב, ז."],["9924","438","<b>ומשכן הנשמה. . החכ' שבמוח</b>: ראה גם לעיל פ' בא קד, ג. וש\"נ."],["9925","439","<b>חיים הם למוצאיהם בפה</b>: משלי ד, כב. ערובין נד, א."],["9926","440","<b>למען תהי' תורת ה' בפיך</b>: בא יג, ט."],["9927","441","<b>[כי] לא על הלחם. . מוצא פי הוי' בד\"ת</b>: נסמן לעיל פ' תצוה שלד, ג."],["9928","442","<b>כי הוא חייך</b>: נצבים ל, כ."],["9929","443","<b>כי אמרתך חייתני</b>: תהלים קיט, נ."],["9930","444","<b>דואהבת [גימ'] ב\"פ אור</b>: פע\"ח (שער הק\"ש) ש\"ח, פכ\"ג. ראה לעיל פ' וארא סה, ג. וש\"נ."],["9931","445","<b>והיו הדברים</b>: ואתחנן ו, ו."],["9932","446","<b>ודברת בם</b>: שם ו, ז."],["9933","447","<b>שמהבל הדבור. . נעשה או\"מ</b>: ראה פע\"ח (שער התפלה) ש\"א, פ\"ד. לעיל פ' בשלח קפא, ב הערה 782."],["9934","448","<b>שם</b>: חט: שלמעלה."],["9935","449","<b>שס\"ר אותיות התורה</b>: ראה מג\"ע אופן קפו. לעיל פ' שמות לב, ב. וש\"נ."],["9936","450","<b>ואשים דברי בפיך</b>: ישעי' נא, טז."],["9937","451","<b>ה' צלך</b>: תהלים קכא, ה. ראה גם לעיל פ' וארא סה, ד. וש\"נ."]]],[2300550564,"ממנו בשרשו הראשון בבחי' מקיף דסתים דאורייתא, ולכך עיקר בחי' הכלי ושרש ומקור הנשמה שהוא בחי' הנשימה שבה ברו\"ש ממקורה הוא דבור דד\"ת דוקא כו', ולכך מצות ת\"ת תמידית בשבתך כו' ובלכתך כו' כמ\"ש בשכבך תשמור עליך<sup data-n=\"9938\">452</sup> כו' וד\"ל). ופי' ודברת בם לשון המשכה והנהגה<sup data-n=\"9939\">453</sup> שתמשיך בחי' רו\"ש הזה דנשמה שבמוח ולב שבואהבת כו' בבחי' כלי שהן אותיות דתורה בדבור דוקא ובלי כלי זה אין קי[ו]ם כלל למציאות רו\"ש דנשמה וד\"ל.\n<b>ואמנם</b> [הנה] זהו דוקא כאשר בחי' הדבור דד\"ת הוא בתכלית בחי' הבטול האמיתי העצמי עד שאינו נראה לבחי' יש ודבר במהות בפ\"ע כלל אז ראוי להיות בחי' כלי לביטול העצמ[י]ת דנשמה ברו\"ש הנ\"ל, והוא כאשר אין הדבור שלו בד\"ת רק בחי' כלי בעלמא לדבר ה' זו הלכה או מקרא שאומר בפיו ולא כאומר דבר עצמו כלל, כמו תען לשוני אמרתיך<sup data-n=\"9940\">454</sup> כמו העונה אחר הקורא כך דבר ה' הוא [ש]מדבר כמ\"ש ואשים דברי בפיך כו', כמו דבר ה' בפי הנביא או המלאך שאינו רק כלי מעבר לדבר ה' שמדבר בו ואז דוקא הדבור דד\"ת נעשה בחי' כלי לרו\"ש הנ\"ל [וד\"ל]. וז\"ש [עבודת הלוים] ביד איתמר פי' עבודת הלוים בנשיאת המשכן בבחי' רו\"ש דאהוי\"ר שבלב ששרשו ברו\"ש דנשמה במוח דחו\"ב שנק' אדם א' ד\"ם כנ\"ל בפנימיות וחצוניות דשם הוי' כנ\"ל, הנה כ\"ז הוא ביד איתמר בן אהרן כו', הנה פי' איתמר<sup data-n=\"9941\">455</sup> כענין איתמר שבגמ' בלשון תרגום כך הוא בלה\"ק מענין ולשון אתאמר<sup data-n=\"9942\">456</sup> שכבר אמור והיינו מצות ת\"ת שאינו רק לדבר דבר ה' שכבר נאמר מפי ה' למשה וממשה לישראל כמ\"ש ודברי אשר שמתי בפיך, אלא שאיתמר בלשון גמ' הוא בלשון תרגום ושם איתמר הוא בלה\"ק שהוא בחי' כלי דבור דד\"ת שהוא עיקר בחי' כלי ל[רצו\"ש ד]נשמה ורוח שזהו כללות התומ\"צ ברו\"ש כנ\"ל, ולכך אמר אשר פקד ע\"פ משה גם עבודת הלוים ברו\"ש שלהם שיהי' להם בחי' כלי וזהו<sup data-n=\"9943\">457</sup> בדבור דד\"ת וז\"ש ביד איתמר דוקא וד\"ל.\n<b>אך</b> הנה [עדיין] י\"ל בזה דעכ\"ז מה שייכות יש לומר דפקד ע\"י משה גם עבודת הלוים ביד איתמר כו' אם עבודת הלוים עיקר הכלי שלהם ביד איתמר דוקא כנ\"ל למה צריך לפקידה דמשה דוקא. ועוד עדיין לא מתורץ הקושי' דלעיל אם אהרן עצמו לא נזכר עם משה במ\"ש אשר פקד כו' איך אומר ביד איתמר בן אהרן כו'. אך הנה יש להקדים עוד ענין א' בפי' איתמר בן אהרן<sup data-n=\"9944\">458</sup> דמשמעות איתמר זה ממילא<sup data-n=\"9945\">459</sup> ומאליו",[["9938","452","<b>בשכבך תשמור עליך</b>: משלי ו, כב."],["9939","453","<b>ודברת. . לשון המשכה והנהגה</b>: ראה גם מאמרי אדה\"א בראשית ע' תיט. וש\"נ. שמות ח\"ב ע' שסח, וש\"נ. תו\"ח לך צא, ב."],["9940","454","<b>תען לשוני אמרתיך</b>: תהלים קיט, קעב."],["9941","455","<b>איתמר</b>: ניתוסף ע\"פ ג."],["9942","456","<b>איתמר. . איתמר שבגמ'. . אתאמר</b>: נסמן לעיל תמה, ד."],["9943","457","<b>וזהו</b>: גחט: לזה."],["9944","458","<b>בן אהרן</b>: חט: זה."],["9945","459","<b>זה ממילא</b>: שם: היינו שממילא."]]],[2300550577,"איתמר<sup data-n=\"9946\">460</sup>, ולא שהדבור ואמירה זו [היא] ברצון ובחירה רק ממילא [ומעצמו] איתמר כמו אז נדברו יראי ה'<sup data-n=\"9947\">461</sup> שנדברו ז[ע]\"ז ממילא שהדבור בא להם פתאום ממילא ומאליו בלתי רצון והכנה לזה הדבור ע\"ז שייך נדברו לשון נפעל שנדבר הדבור ממילא, אבל אם הי' הדבור מכח האדם שמצד שכלו ורצונו מדבר אז שייך לשון מדברים או דוברים, אך לשון נדבר ענינו לשון נפעל שהדבור נפעל ונדבר ממילא ומאליו (וכך הוא בעצם כח הדבור באדם שנק' רוח ממללא<sup data-n=\"9948\">462</sup> נפש המדברת<sup data-n=\"9949\">463</sup> בחי' מדבר שזהו ענין<sup data-n=\"9950\">464</sup> שלימות האדם נפש השכלית, אע\"פ שנק' מדבר מ\"מ ענינו שהדבור בא בנפש המדברת [מאליו ו]ממילא דוקא מכח קדמות השכל שלמעלה מגלוי אור השכל מן ההעלם, שמשם נמשך כח הדבור לצרף צרופי אותיות הדבור ממילא ומאליו בלתי בחירה ורצון באופן סדר [ה]צרופים כלל. כי מה שבא אור החכ' מאין ליש בהשגה בבינה זה[ו] הבא בדבור בסדר והדרגה שיודע ומכוון מה שמדבר ומכלכל דבריו במשפט השכל שבמוח בינה, אבל כח עצמיות השכל קודם שמשכיל [כל] שכל בגלוי שא\"א שיבא בגלוי דחו\"ב משם דוקא נמשך כח המדבר באדם שזהו דבור הבא ממילא בלי כוונה בשכל שבמוח כלל אלא נדבר מעצמו, כמו הטרוד מאד בעמקו של שכל שלומד שבא לבחי' האין דחכ' קודם שבאה לגלוי בהשגה אז מתרחשים שפתיו בחשאי<sup data-n=\"9951\">465</sup> ולא ירגיש כלל בדבור זה כי [יבא] דבור זה ממילא ומאליו מטעם הנ\"ל כמ\"ש במ\"א ע\"פ ומדברך נאוה<sup data-n=\"9952\">466</sup> כו', וזהו דבור דד\"ת מאליו כנ\"ל וד\"ל).\n<b>וכך</b> יש ג\"כ בדבור דתפילה שנק' צלותא בלחש<sup data-n=\"9953\">467</sup> שהדבור יוצא מקירות הלב ממילא ומאליו בלי בחירה ורצון כמו וחנה מדברת על לבה<sup data-n=\"9954\">468</sup> כו', והוא מנקודת הרצון טרם שבא לגלוי בטעם וכוונה לרצון כו' [(וכמו<sup data-n=\"9955\">472</sup> אדני ש\"ת<sup data-n=\"9956\">470</sup> כו' אין מלה בלשוני<sup data-n=\"9957\">471</sup> כו')<sup data-n=\"9958\">469</sup> ]. וכך הוא בפי' איתמר זה בלשון תרגום שהוא דבור הנדבר ונאמר ממילא ומאליו דוקא. וכמ\"כ הוא מענין הדבור בד\"ת שצ\"ל בתכלית הבטול שבא מצד העדר הרגשה בעצמו מצד היותו בטל בתכלית לדבר ה' זו הלכה וכמו אדני שפתי כו' אין מלה כו' [עד] שנדבר ונאמר ממילא ומאליו בפיו, ואין דבור זה בא מצד עצמו כלל אלא נדבר בו דבר ה' מאליו וממילא כענין אז נדברו כו' וכמו תען לשוני אמרתיך כו' תען בלי בחירה ורצון אלא רק מאליו יבא בו דבור זה מפני שהקב\"ה יושב ושונה כנגדו ואינו אלא כלי להכיל דבר ה'",[["9946","460","<b>איתמר. . ממילא. . איתמר</b>: נסמן לעיל תמה, ד."],["9947","461","<b>אז נדברו יראי ה'</b>: מלאכי ג, טז."],["9948","462","<b>רוח ממללא</b>: ת\"א לבראשית ב, ז."],["9949","463","<b>נפש המדברת</b>: ראה גם לעיל פ' וארא פא, ג. וש\"נ."],["9950","464","<b>ענין</b>: חט: עיקר."],["9951","465","<b>הטרוד. . מתרחשים שפתיו בחשאי</b>: ראה גם מאמרי אדה\"א נ\"ך ע' יט. וש\"נ. תו\"ח נח נב, ג ובהערה 27."],["9952","466","<b>ומדברך נאוה</b>: שה\"ש ד, ג. ראה גם לעיל פ' יתרו רנה, ד."],["9953","467","<b>צלותא בלחש</b>: זהר ח\"ש קלב, א. ויגש רי, א. תרומה קלח, ב. ועוד. ראה מאמרי אדה\"א בראשית ע' צט. וש\"נ."],["9954","468","<b>וחנה מדברת על לבה</b>: שמו\"א א, יג [ושם: וחנה היא — ראה מאמרי אדה\"א קונטרסים ע' תצ. וש\"נ]."],["9955","472","<b>וכמו. . כו'</b>: חט: ליתא. ראה לעיל הערה 469."],["9956","470","<b>אדני ש\"ת</b>: תהלים נא, יז."],["9957","471","<b>אין מלה בלשוני</b>: תהלים קלט, ד."],["9958","469","<b>(וכמו. . כו')</b>: ניתוסף ע\"פ חט. וראה בסמוך הערה 472."]]],[2300550588,"המדבר בו ממילא כו'. וכדוגמא זו הי' בהרב ב\"י שהי' המגיד מדבר בפיו למוד משניות עד שאמר אני המשנה המדברת בפיך<sup data-n=\"9959\">473</sup> לפי שהי' לימודו ע\"ד הנ\"ל רק כלי לדבר ה' זו המשנה המדברת בפיו וד\"ל.\n<b>וזהו</b> אשר פקד ע\"פ משה עבודת הלוים ביד איתמר, דהנה שרש נשמת משה מבחי' פנימיות ומקור החכ' כמו שהיא בבחי' אין דכתר ממש כמ\"ש בו מן המים משיתיהו<sup data-n=\"9960\">474</sup> וע\"כ הי' ג\"כ כבד פה ולשון<sup data-n=\"9961\">475</sup> שלא הי' יכול לבא בדבור בתושבע\"פ ותושב\"כ מטעם הנ\"ל, ועכ\"ז נאמר משה ידבר כו' דהיינו שהי' הדבור מדבר בו ממילא ומאליו מכח ומקור החכ' העצמיות שמשם נמשך אור דתורה מאין ליש כו'. וז\"ש דשכינה מדברת מתוך גרונו של משה<sup data-n=\"9962\">476</sup> פי' שכינה הוא בחי' מל' שנק' דבור<sup data-n=\"9963\">477</sup> והוא בחי' ח\"ת חכ' שבדבור [והיא] תושבע\"פ מתניתא מלכתא<sup data-n=\"9964\">478</sup> והיתה מדברת בדבור הבא מאליו מתוך גרונו של משה כמו גם עכשיו בכל איש שיושב ושונה כו', כי הי' רק כלי לדבר ה' שבח\"ע [ה]עצמ[י]ת ממש ע\"כ הי' הדבור יוצא בגרונו ממילא כו' וד\"ל. וז\"ש אשר פקד פקידה זו בפנימיות ומקור החכ' שהוא שרש לרו\"ש בדפק בחצוניות דחכ' בבינה ומדות שבלב שהוא עבודת הלוים ברו\"ש כנ\"ל. וזהו שפקד גם עבודת הלוים להיות בבחי' רו\"ש בכלי [ה]דבור בד\"ת ע\"י משה דוקא לפי שהוא שרש [ה]ראשון לזה וכענין שכינה היתה מדברת כנ\"ל וד\"ל.\n<b>וזהו</b> סדר פ' א' דק\"ש בתחלה יחו\"ע דהוי' אלקינו (ויחו\"ת דבשכמל\"ו ) ואח\"כ בחי' רו\"ש דואהבת ואח\"כ ודברת בם שזהו בחי' הכלי לבחי' הבטול דרו\"ש דחו\"ב ומדות, שזהו בחי' איתמר הנ\"ל שבידו דוקא ניתנו עבודת הלוים ע\"פ משה דוקא כו' וד\"ל. ואח\"כ אמר וקשרתם לאות שהוקשו כל המצות לתפילין<sup data-n=\"9965\">479</sup> שזהו בחי' מעשה עצמה דמצות שהן בחי' כלים רבים לאור הקדושה [ה]אלק[י]ת דשם הוי' שהן מתחלקים באופנים שונים כמו ברמ\"ח מ\"ע ועכ\"ז הגם שמתחלקים לפרטים רבים יש בכללותם יחד התכללות כמו כלי א' ממש וכמ\"ש כי נר מצוה שכללות המצות נק' נר. וכמו שיש בפרט בכל מצוה המשכות אור הקדושה דשם הוי' בפרט ונק' מצות הוי' כך יש בכללותם יחד מקדושה הכללית דשם הוי' כמ\"ש ועשיתם [את] כל מצותי<sup data-n=\"9966\">480</sup> והייתם קדושים, וכמו שיש בכל מצוה בפרט העלאה והמשכה",[["9959","473","<b>אני המשנה המדברת בפיך</b>: ראה גם לעיל פ' תצוה שסב, ד. וש\"נ."],["9960","474","<b>מן המים משיתיהו </b>[ג ניתוסף: ח\"ע כו'. ח ניתוסף: מ\"ע כו']: שמות ב, י. ראה גם לעיל פ' שמות מג, א. וש\"נ."],["9961","475","<b>כבד פה ולשון. . בתושבע\"פ ותושב\"כ</b>: ראה גם לעיל פ' יתרו רנו, ג. וש\"נ."],["9962","476","<b>דשכינה מדברת מתוך גרונו של משה</b>: ראה תניא פל\"ד. לעיל פ' בשלח קצד, ד הערה 540."],["9963","477","<b>מל' שנק' דבור</b>: ראה זהר לך פו, ב. לעיל פ' שמות לד, א. וש\"נ."],["9964","478","<b>מתניתא מלכתא</b>: כתובות סא, ב. חט: מתניתין מלכתא — ביצה כח, ב."],["9965","479","<b>וקשרתם לאות שהוקשו כל המצות לתפילין</b>: ראה גם לעיל פ' וארא סט, א. וש\"נ."],["9966","480","<b>ועשיתם [את] כל מצותי</b>: שלח טו, מ."]]],[2300550599,"יחד בבחי' רו\"ש שהוא בחי' אהוי\"ר שבה בקבלת עומ\"ש באה' ורצון וביראה ובפחד. אך בחי' הכלי להחזיק לבחי' רו\"ש זה זהו המצוה בעצמה שנק' נר כמ\"ש כי נר מצוה כמו הנר הוא כלי לאור המתנענע כו', וכמו שכלי דבור בד\"ת נק' כלי לבחי' רו\"ש דחכ' שבמוח והיינו לאור דתורה כנ\"ל בענין אשר פקד ונק' איתמר כו' ממילא כו' כענין שכינה מדברת כו' והוא שרש הדבור במקור החכ', כך יש בחי' כלי ממש במצוה בפו\"מ לבחי' רו\"ש דאהוי\"ר שבלב. הגם שהוא עבודת הלוים להעלות השכינה ולהורידה ברו\"ש ביחו\"ע ג\"כ שנק' י\"ה משכן העדות שזהו הכלי דדבור דד\"ת דאיתמר הנ\"ל, מ\"מ יש בחי' כלי במעשה המצות שנק' נר מצוה לאהוי\"ר שבמעשה כמו נר הוי' נשמת אדם ברו\"ש דנשמה הנ\"ל רק שאינו בבחי' בטול כ\"כ כדבור דד\"ת כי הוא מלובש במעשה ממש. וז\"ש כי קרוב אליך הדבר<sup data-n=\"9967\">481</sup> בפיך זו תורה ובלבבך זו תשובה ומע\"ט לעשותם<sup data-n=\"9968\">482</sup> בפו\"מ (ולפי שנתב\"ס בסוף מעשה דוקא ע\"כ גדול שרש דנר מצוה מנר הוי' נשמת אדם בדבור דד\"ת, וע\"כ אמרו הלומד ואינו עושה<sup data-n=\"9969\">483</sup> כו' אע\"פ שתלמוד גדול כו'<sup data-n=\"9970\">484</sup> זיל בתר טעמא<sup data-n=\"9971\">485</sup> כו' [וד\"ל]. וז\"ש ראשית חכ' כו' שכל טוב לעושיהם ולא ללומדיהם<sup data-n=\"9972\">486</sup> אע\"פ שעל מוצא פי הוי' שבתורה יחי' האדם לא המדרש עיקר<sup data-n=\"9973\">487</sup> [כו'], וז\"ש נר מצוה דוקא אז תורה אור בדבור ברו\"ש. וז\"ש והי' אם שמוע<sup data-n=\"9974\">488</sup> לקבל עליו עול מצות ברו\"ש כמ\"ש לאה' את ה' ולעבדו דאהוי\"ר זו במעשה עצמה שרשה עליון יותר מרו\"ש דאהוי\"ר",[["9967","481","<b>כי קרוב אליך הדבר</b>: נצבים ל, יד [בדילוג]. ראה גם תורת חיים וישב ר, א."],["9968","482","<b>לעשותם</b>: ט: לעשותו."],["9969","483","<b>הלומד ואינו עושה</b>: ראה ירושלמי ברכות פ\"א, ה\"ב. ראה גם לקוטי תורה אחרי כו, ב ובהנסמן במ\"מ לשם."],["9970","484","<b>כו'</b>: חט: מפני שמביא לידי מעשה."],["9971","485","<b>זיל בתר טעמא</b>: ראה ר\"ן נדרים נב, א. תוי\"ט נדרים פ\"ב. מ\"א. ועוד. גיטין עג, א."],["9972","486","<b>ראשית חכ'. . לעושיהם ולא ללומדיהם</b>: תהלים קיא, י. ראה ברכות יז, א [הגי' שעה\"ג שם]. יל\"ש תהלים שם (רמז תתע)."],["9973","487","<b>לא המדרש עיקר</b>: אבות פ\"א, מי\"ז [כגי' אדה\"ז בסידורו]."],["9974","488","<b>והי' אם שמוע</b>: עקב יא, יג."]]],[2300550610,"דואהבת ומרו\"ש דדבור דחכ' דתורה ג\"כ מטעם דנתב\"ס דוקא וד\"ל.\n<b>ונמצא</b> [מ]ובן מכל הנ\"ל בפסוק זה דאלה פקודי עד ביד איתמר שזהו ג\"כ ענין סדר התפלה תחלה בפסד\"ז שהוא בחי' רו\"ש דלוים בנשיאת המשכן בעלי' וירידה כנ\"ל וכן בשתים לפניה יוצר אור [שאו' ביראה] ואה\"ע ו[אח\"כ] בק\"ש ענין היחו\"ע דמשכן העדות די\"ה ומשכן סתם ואח\"כ ואהבת ודברת בם שזהו אשר פקד ע\"פ משה עבודת הלוים ביד איתמר דוקא כנ\"ל וד\"ל. ומ\"ש ביד איתמר בן אהרן אע\"פ שלא הזכיר אהרן עם משה בתחלה, לפי שבחי' אהרן כה\"ר העליון היינו כח [ה]אה\"ר [ה]עליונה שלמעלה מן החכ' לגמרי שמושך האה[\"ר] בכנ\"י וע\"כ יש בו כח להמשיך לעשות כל סדר עבודה הזאת דלוים ברו\"ש ביד איתמ\"ר כו' שהוא רו\"ש דדבור דחכ' שיהי' כלי לרו\"ש דנשמה להעלותה למעלה כמ\"ש באהרן בהעלותך את הנרות<sup data-n=\"9975\">489</sup> כמ\"ש במ\"א שהן נרות דנשמה<sup data-n=\"9976\">490</sup> שנק' נר הוי' ולכך דקדק לומר בן אהרן הכהן דוקא וד\"ל.",[["9975","489","<b>בהעלותך את הנרות</b>: ראה גם לעיל פ' יתרו רסט, סע\"ב ואילך. וש\"נ."],["9976","490","<b>דנשמה</b>: חט: דנש\"י."]]]]});
